// Patches the android/ folder generated by `flutter create`:
// permissions, "open with / share" filters, notification receivers,
// desugaring for notifications, app name and the native MainActivity.
// Safe to run multiple times:  dart run tool/patch_platforms.dart
import 'dart:io';

void patch(String path, String Function(String) change) {
  final f = File(path);
  if (!f.existsSync()) return;
  final before = f.readAsStringSync();
  final after = change(before);
  if (after != before) {
    f.writeAsStringSync(after);
    stdout.writeln('patched $path');
  }
}

const shareFilters = '''
            <intent-filter>
                <action android:name="android.intent.action.SEND"/>
                <category android:name="android.intent.category.DEFAULT"/>
                <data android:mimeType="application/pdf"/>
                <data android:mimeType="image/*"/>
                <data android:mimeType="application/vnd.apple.pkpass"/>
                <data android:mimeType="application/vnd-com.apple.pkpass"/>
                <data android:mimeType="application/octet-stream"/>
            </intent-filter>
            <intent-filter>
                <action android:name="android.intent.action.VIEW"/>
                <category android:name="android.intent.category.DEFAULT"/>
                <category android:name="android.intent.category.BROWSABLE"/>
                <data android:scheme="content"/>
                <data android:scheme="file"/>
                <data android:mimeType="application/vnd.apple.pkpass"/>
                <data android:mimeType="application/vnd-com.apple.pkpass"/>
            </intent-filter>
''';

const receivers = '''
        <receiver android:exported="false" android:name="com.dexterous.flutterlocalnotifications.ScheduledNotificationReceiver"/>
        <receiver android:exported="false" android:name="com.dexterous.flutterlocalnotifications.ScheduledNotificationBootReceiver">
            <intent-filter>
                <action android:name="android.intent.action.BOOT_COMPLETED"/>
                <action android:name="android.intent.action.MY_PACKAGE_REPLACED"/>
                <action android:name="android.intent.action.QUICKBOOT_POWERON"/>
                <action android:name="com.htc.intent.action.QUICKBOOT_POWERON"/>
            </intent-filter>
        </receiver>
''';

void main() {
  patch('android/app/src/main/AndroidManifest.xml', (s) {
    const perms = [
      'android.permission.INTERNET',
      'android.permission.POST_NOTIFICATIONS',
      'android.permission.RECEIVE_BOOT_COMPLETED',
      'android.permission.VIBRATE',
    ];
    final block = perms
        .where((p) => !s.contains(p))
        .map((p) => '    <uses-permission android:name="$p"/>\n')
        .join();
    if (block.isNotEmpty) {
      final m = RegExp(r'<manifest[^>]*>\s*\n').firstMatch(s);
      if (m != null) s = s.replaceRange(m.end, m.end, block);
    }
    if (!s.contains('android.intent.action.SEND')) {
      final i = s.indexOf('</intent-filter>');
      if (i > 0) {
        final end = s.indexOf('\n', i) + 1;
        s = s.replaceRange(end, end, shareFilters);
      }
    }
    if (!s.contains('ScheduledNotificationReceiver')) {
      s = s.replaceFirst('    </application>', '$receivers    </application>');
    }
    return s.replaceFirst(RegExp(r'android:label="[^"]*"'), 'android:label="Nflight"');
  });

  // Notifications need core library desugaring; scanner needs a recent minSdk.
  patch('android/app/build.gradle.kts', (s) {
    if (!s.contains('isCoreLibraryDesugaringEnabled')) {
      s = s.replaceFirst('compileOptions {', 'compileOptions {\n        isCoreLibraryDesugaringEnabled = true');
    }
    s = s.replaceFirst(RegExp(r'minSdk = [^\n]+'), 'minSdk = 24');
    // Same key on every build (CI and PC) so a new APK installs over the old one.
    if (!s.contains('tool/debug.keystore')) {
      s = s.replaceFirst('android {', 'android {\n    signingConfigs {\n        getByName("debug") {\n            storeFile = file("../../tool/debug.keystore")\n        }\n    }');
    }
    if (!s.contains('desugar_jdk_libs')) {
      s += '\ndependencies {\n    coreLibraryDesugaring("com.android.tools:desugar_jdk_libs:2.1.4")\n}\n';
    }
    return s;
  });
  patch('android/app/build.gradle', (s) {
    if (!s.contains('coreLibraryDesugaringEnabled')) {
      s = s.replaceFirst('compileOptions {', 'compileOptions {\n        coreLibraryDesugaringEnabled true');
    }
    s = s.replaceFirst(RegExp(r'minSdk(Version)? [^\n]+'), 'minSdkVersion 24');
    if (!s.contains('desugar_jdk_libs')) {
      s += "\ndependencies {\n    coreLibraryDesugaring 'com.android.tools:desugar_jdk_libs:2.1.4'\n}\n";
    }
    return s;
  });

  final kt = File('tool/android/MainActivity.kt');
  final ktDir = Directory('android/app/src/main/kotlin/ro/noraz/nflight');
  if (kt.existsSync() && ktDir.existsSync()) {
    kt.copySync('${ktDir.path}/MainActivity.kt');
    stdout.writeln('copied MainActivity.kt');
  }
}
